package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import com.northstarbank.console.integration.TierClient;import com.northstarbank.console.security.AuthorizationService;import java.util.*;import org.springframework.stereotype.Service;
@Service public class CustomerService{private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(CustomerService.class);private final TierClient tiers;private final AuthorizationService auth;private final AuditService audit;private final NoteRepository notes;private final DocumentRepository docs;private final TelephoneCredentialRepository credentials;public CustomerService(TierClient t,AuthorizationService a,AuditService log,NoteRepository n,DocumentRepository d,TelephoneCredentialRepository tc){tiers=t;auth=a;audit=log;notes=n;docs=d;credentials=tc;}
 public List<TierClient.Customer> search(String q){auth.require("SEARCH",null,false);var x=tiers.search(auth.user().token(),q);audit.record("CUSTOMER_SEARCH","customer",x.size(),null,"effective_scope",null,"query-results="+x.size());return x;}
 // Precision location: the controller delegates its ownership/scope check to this shared service one call frame above it.
 public CustomerPage view(String id){var page=tiers.customer(auth.user().token(),id);var d=auth.require("CUSTOMER_VIEW",page.customer().branch(),page.customer().vulnerable());audit.record("CUSTOMER_READ","customer",1,id,d.authorizationBasis(),null,"read");return new CustomerPage(page,notes.findByCustomerIdOrderByCreatedAtDesc(id),docs.findByCustomerIdOrderByCreatedAtDesc(id));}
 public void updateContact(String id,String phone,String email){var before=tiers.customer(auth.user().token(),id).customer();var d=auth.require("CUSTOMER_EDIT",before.branch(),before.vulnerable());var after=tiers.updateContact(auth.user().token(),id,phone,email);
  LOG.info("Contact details for {} changed from {} / {} to {} / {}",id,before.phone(),before.email(),after.phone(),after.email());
  audit.record("CONTACT_UPDATED","customer",1,id,d.authorizationBasis(),before.phone()+"/"+before.email(),after.phone()+"/"+after.email());}
 public void setTelephonePin(String id,String pin,String branch){auth.require("CUSTOMER_EDIT",branch,false);byte[] salt=new byte[8];new java.security.SecureRandom().nextBytes(salt);TelephoneCredential credential=credentials.findById(id).orElseGet(TelephoneCredential::new);credential.customerId=id;credential.salt=java.util.HexFormat.of().formatHex(salt);credential.digest=derivePin(pin,salt);credential.updatedAt=java.time.Instant.now();credentials.save(credential);audit.record("TELEPHONE_PIN_SET","customer",1,id,"effective_scope",null,"telephone-pin");}
 public boolean verifyTelephonePin(String id,String pin){TelephoneCredential credential=credentials.findById(id).orElseThrow();return java.security.MessageDigest.isEqual(derivePin(pin,java.util.HexFormat.of().parseHex(credential.salt)).getBytes(java.nio.charset.StandardCharsets.UTF_8),credential.digest.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 private String derivePin(String pin,byte[] salt){try{javax.crypto.SecretKeyFactory factory=javax.crypto.SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");javax.crypto.spec.PBEKeySpec spec=new javax.crypto.spec.PBEKeySpec(pin.toCharArray(),salt,1024,128);return java.util.HexFormat.of().formatHex(factory.generateSecret(spec).getEncoded());}catch(Exception e){throw new IllegalStateException(e);}}
 public record CustomerPage(TierClient.Customer360 core,List<CaseNote> notes,List<CaseDocument> documents){}
}
